import Foundation
import RealityKit

/// Sample mode: matches prompts by keyword to built-in low-poly objects and base templates.
/// Nothing is generated by AI; the notes say what was matched.
struct SampleModelGenerationService: ModelGenerationService {
    let source: ModelSource = .sample

    func generateObject(prompt: String) async throws -> GeneratedModel {
        let match = SampleObjectCatalog.match(prompt)
        let colorPrefix = match.colorName.map { "\($0.capitalized) " } ?? ""

        guard let kind = match.kind, let keyword = match.keyword else {
            return GeneratedModel(
                displayName: "\(colorPrefix)Placeholder",
                source: .sample,
                recipe: .placeholder(color: match.colorName),
                entity: SampleObjectCatalog.makePlaceholder(tint: match.color),
                note: "No sample object matches that prompt, so a placeholder block was placed."
            )
        }

        return GeneratedModel(
            displayName: colorPrefix + kind.name,
            source: .sample,
            recipe: .sampleObject(kind: kind.rawValue, color: match.colorName),
            entity: SampleObjectCatalog.make(kind, tint: match.color),
            note: "Sample: matched “\(keyword)” to the built-in \(kind.name.lowercased())."
        )
    }

    func generateBase(prompt: String) async throws -> GeneratedModel {
        let words = SampleObjectCatalog.words(in: prompt)
        var best: (template: BaseTemplate, keyword: String, position: Int)?
        for template in BaseTemplate.allCases {
            for keyword in template.keywords {
                if let position = SampleObjectCatalog.position(of: keyword, in: words),
                   best.map({ position < $0.position }) ?? true {
                    best = (template, keyword, position)
                }
            }
        }

        let template = best?.template ?? .grass
        let note = best.map { "Sample: matched “\($0.keyword)” to the \($0.template.name) template." }
            ?? "No sample base matches that prompt, so the Grass template was used."
        return GeneratedModel(
            displayName: template.name,
            source: .sample,
            recipe: .baseTemplate(template.rawValue),
            entity: BaseTemplateBuilder.make(template),
            note: note
        )
    }
}
